for lang,(title,subtitle,short,a,b) in copy.items():
    sentences=[x for x in re.split(r'(?<=[.!?])\s+',short) if x]
    assert len(sentences)==6,(lang,len(sentences))
    assert all(len(x.split())<=22 for x in sentences),(lang,[len(x.split()) for x in sentences])
    assert 60<=len((a+' '+b).split())<=250,(lang,len((a+' '+b).split()))
    m['title'][lang]=title;m['subtitle'][lang]=subtitle;m['shortDescription'][lang]=short;m['aboutBook'][lang]=[a,b]
m['shortDescriptionEditorial']={'method':'author-reviewed from source and ten-minute reader','sourceSha256':m['metadataDraft']['sourceSha256'],'sentencesPerLanguage':6,'status':'reviewed'}
